// Transform fullscreen element IN-PLACE into flex container, move children
const children = Array.from(playerShell.children).filter(c => c.id !== 'cell-subtitle-root');
for (const child of children) stageCell.appendChild(child); // move children, NOT playerShell
playerShell.style.display = 'flex';
playerShell.style.flexDirection = 'row';
playerShell.appendChild(stageCell);
playerShell.appendChild(handle);
playerShell.appendChild(panel); // playerShell stays top-layer, no exit

// Re-request fullscreen on parent container (can host flex siblings)
if (document.fullscreenElement?.tagName === 'VIDEO') {
  const parent = video.parentElement;
  await document.exitFullscreen();
  await parent.requestFullscreen(); // parent is a container → can be flex
  // effect re-runs on fullscreenchange, findPlayerContainer returns parent
} else {
  fullscreenEl.appendChild(panel); // container can host siblings
}
